import { useEffect, useState } from "react";
import {
  crearEvaluacionPsico,
  actualizarEvaluacionPsico,
  listarEvaluacionesIntegrales,
} from "../../servicios/evaluacionPsico";

function EvaluacionPsicoForm({ evaluacion, onSuccess }) {
  const [formData, setFormData] = useState({
    evaluacion_integral: "",
    fecha: "",
    evaluador: "",
    observaciones: "",
  });

  const [integrales, setIntegrales] = useState([]);

  useEffect(() => {
    listarEvaluacionesIntegrales().then(setIntegrales);

    if (evaluacion) {
      setFormData({
        evaluacion_integral: evaluacion.evaluacion_integral,
        fecha: evaluacion.fecha || "",
        evaluador: evaluacion.evaluador || "",
        observaciones: evaluacion.observaciones || "",
      });
    }
  }, [evaluacion]);

  const handleChange = (e) => {
    setFormData({
      ...formData,
      [e.target.name]: e.target.value,
    });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();

    try {
      if (evaluacion?.id) {
        await actualizarEvaluacionPsico(evaluacion.id, formData);
      } else {
        await crearEvaluacionPsico(formData);
      }

      onSuccess();
    } catch (err) {
      console.error(err);
      alert("❌ Error al guardar la evaluación");
    }
  };

  return (
    <form onSubmit={handleSubmit}>
      <label className="form-label">Evaluación Integral</label>
      <select
        className="form-select"
        name="evaluacion_integral"
        value={formData.evaluacion_integral}
        onChange={handleChange}
        required
      >
        <option value="">Seleccione…</option>
        {integrales.map((ev) => (
          <option key={ev.id} value={ev.id}>
            {ev.id} — {ev.estado}
          </option>
        ))}
      </select>

      <label className="form-label mt-3">Fecha</label>
      <input
        type="date"
        className="form-control"
        name="fecha"
        value={formData.fecha}
        onChange={handleChange}
      />

      <label className="form-label mt-3">Evaluador</label>
      <input
        type="text"
        className="form-control"
        name="evaluador"
        value={formData.evaluador}
        onChange={handleChange}
        required
      />

      <label className="form-label mt-3">Observaciones</label>
      <textarea
        className="form-control"
        name="observaciones"
        rows="3"
        value={formData.observaciones}
        onChange={handleChange}
      ></textarea>

      <button className="btn btn-success mt-3 w-100">
        {evaluacion ? "Actualizar" : "Crear evaluación"}
      </button>
    </form>
  );
}

export default EvaluacionPsicoForm;
